{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/parts/bar-chart.json
    A row of vertical bars (sales by day, orders by week) with a caption under each bar. The chart is one image for assistive technology: `label` carries the summary, the bar values are in the captions and titles.
    Props (p): bars, label, max, height, className. -#}
{%- set v_bars = (p.bars ?? null) -%}
{%- set v_label = (p.label ?? null) -%}
{%- set v_max = (p.max ?? null) -%}
{%- set v_height = (p.height ?? 160) -%}
{%- set v_top = og_max([1, og_coalesce([v_max, og_max_by(v_bars, 'value')])]) -%}
{%- set c_6 -%}
  {%- set c_2 -%}
    {%- for v_b in og_l(v_bars) %}
      {%- set c_1 -%}
        {{ include('compose/Box.html.twig', {'class': og_s(og_cnv(['w-full rounded', (og_t(og_get(v_b, ['muted'])) ? 'bg-muted-foreground' : 'bg-primary')])), 'attrs': og_attrs(['style', og_css(['height', og_max([2, og_round(og_mul(og_div(og_get(v_b, ['value']), v_top), 100))]), '%']), 'data-bar', og_get(v_b, ['id'])])}, with_context = false) }}
      {%- endset -%}
      {{ include('compose/Box.html.twig', {'class': 'flex h-full min-w-0 flex-1 items-end', 'attrs': og_attrs(['title', og_coalesce([og_get(v_b, ['title']), og_get(v_b, ['label'])])]), 'children': c_1}, with_context = false) }}
    {%- endfor %}
  {%- endset -%}
  {{ include('compose/Box.html.twig', {'class': 'flex min-w-0 items-end gap-2', 'attrs': og_attrs(['role', 'img', 'aria-label', v_label, 'style', og_css(['height', v_height, 'px'])]), 'children': c_2}, with_context = false) }}
  {%- set c_5 -%}
    {%- for v_b in og_l(v_bars) %}
      {%- set c_4 -%}
        {%- set c_3 -%}
          {{ og_text(og_get(v_b, ['label'])) }}
        {%- endset -%}
        {{ include('compose/Text.html.twig', {'class': 'absolute left-1/2 top-0 m-0 -translate-x-1/2 whitespace-nowrap text-xs font-medium text-muted-foreground', 'children': c_3}, with_context = false) }}
      {%- endset -%}
      {{ include('compose/Box.html.twig', {'class': 'relative h-4 min-w-0 flex-1', 'children': c_4}, with_context = false) }}
    {%- endfor %}
  {%- endset -%}
  {{ include('compose/Box.html.twig', {'class': 'mt-2 flex min-w-0 gap-2', 'attrs': og_attrs(['aria-hidden', 'true']), 'children': c_5}, with_context = false) }}
{%- endset -%}
{{ include('compose/Box.html.twig', {'class': og_s(og_cnv(['min-w-0', (p.className ?? '')])), 'attrs': og_attrs(['data-slot', 'bar-chart']), 'children': c_6}, with_context = false) }}
